// Accessors for src/constants/items.json (contract section 3.7.3). The JSON is generated by
// scripts/build-items.mjs from Valve's public item schema text; see that script for the key meanings.

import itemsJson from '@constants/items.json'
import { CLASS_MAP } from '@constants/mappings'

export interface ItemInfo {
  def: number
  name: string
  itemClass: string
  slot: string
  classes: string[]
  kind: string
  icon?: string
  weaponMode?: number
  chargeType?: number
  buffType?: number
  projectileType?: number
  minViewmodelOffset?: [number, number, number]
}

/** Raw items.json entry (short keys, see scripts/build-items.mjs). */
interface RawItem {
  n: string
  c: string
  s: string
  u: string[]
  k: string
  i?: string
  o?: string
  cs?: Record<string, string>
  wm?: number
  ct?: number
  bt?: number
  pt?: number
}

const RAW_ITEMS = itemsJson as unknown as Record<string, RawItem>
const NO_ITEM = 65535

const infoCache = new Map<number, ItemInfo | null>()
let wearableDefList: number[] | null = null

const rawItem = (def: number): RawItem | undefined =>
  Number.isInteger(def) && def >= 0 && def !== NO_ITEM ? RAW_ITEMS[String(def)] : undefined

const parseOffset = (text: string | undefined): [number, number, number] | undefined => {
  if (!text) return undefined
  const parts = text.trim().split(/\s+/).map(Number)
  if (parts.length !== 3 || parts.some(v => !Number.isFinite(v))) return undefined
  return [parts[0], parts[1], parts[2]]
}

/** Null for 65535 or unknown. */
export function itemInfo(def: number): ItemInfo | null {
  const cached = infoCache.get(def)
  if (cached !== undefined) return cached

  const raw = rawItem(def)
  let info: ItemInfo | null = null
  if (raw) {
    info = { def, name: raw.n, itemClass: raw.c, slot: raw.s, classes: raw.u, kind: raw.k }
    if (raw.i !== undefined) info.icon = raw.i
    if (raw.wm !== undefined) info.weaponMode = raw.wm
    if (raw.ct !== undefined) info.chargeType = raw.ct
    if (raw.bt !== undefined) info.buffType = raw.bt
    if (raw.pt !== undefined) info.projectileType = raw.pt
    const offset = parseOffset(raw.o)
    if (offset) info.minViewmodelOffset = offset
  }

  infoCache.set(def, info)
  return info
}

/** 'Unknown' fallback. */
export function itemName(def: number): string {
  return rawItem(def)?.n ?? 'Unknown'
}

/** items.json `k`, 'other' fallback. */
export function itemKind(def: number): string {
  return rawItem(def)?.k ?? 'other'
}

/** `cs[className]` override, else `s` ('' for unknown items). */
export function itemSlot(def: number, classId: number): string {
  const raw = rawItem(def)
  if (!raw) return ''
  const className = CLASS_MAP[classId]
  return (className && raw.cs?.[className]) || raw.s
}

/** items.json `i`: kill icon basename in src/assets/kill_icons/. */
export function killIconFor(def: number): string | undefined {
  return rawItem(def)?.i
}

/** Defs whose `c` starts with 'tf_wearable' (options.wearableDefs), ascending. */
export function wearableDefs(): number[] {
  if (!wearableDefList) {
    wearableDefList = Object.keys(RAW_ITEMS)
      .filter(key => RAW_ITEMS[key].c.startsWith('tf_wearable'))
      .map(Number)
      .sort((a, b) => a - b)
  }
  return wearableDefList.slice()
}
